CREATE OR REPLACE FUNCTION public.app_mutate_v160_pre_access_codes_060(p_operation text, p_payload jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$ declare v_payload jsonb:=coalesce(p_payload,'{}'::jsonb);v_code text:=upper(trim(coalesce(v_payload->>'invite_code','')));v_uid uuid:=auth.uid();v_email text:=lower(coalesce(auth.jwt()->>'email',''));v_inv public.invitaciones_club;v_club public.clubes;v_existing public.app_mutation_requests;v_result jsonb; begin if p_operation='cuenta.registrar' and v_code<>'' then if v_uid is null then raise exception 'AUTH_REQUIRED';end if;select * into v_existing from public.app_mutation_requests where request_id=p_request_id;if v_existing.request_id is not null and v_existing.user_id=v_uid and v_existing.operation=p_operation and v_existing.result is not null then return v_existing.result;end if;select * into v_inv from public.invitaciones_club i where upper(i.codigo)=v_code and i.tipo_invitacion='alumno' and i.estado='pendiente' for update;if v_inv.id is null then raise exception 'Código de alumno no válido';end if;if v_inv.expira_en<=now() then update public.invitaciones_club set estado='caducada' where id=v_inv.id;raise exception 'La invitación de alumno ha caducado';end if;if lower(v_inv.email)<>v_email then raise exception 'La invitación pertenece a otro correo';end if;select * into v_club from public.clubes where id=v_inv.club_id and activo;if v_club.id is null then raise exception 'Club no disponible';end if;v_payload:=jsonb_set(v_payload,'{club_slug}',to_jsonb(v_club.slug),true);v_result:=public.app_mutate_v160_pre_invites_059(p_operation,v_payload,p_request_id);update public.invitaciones_club set estado='aceptada',aceptado_por=v_uid,aceptado_en=now() where id=v_inv.id;v_result:=jsonb_set(v_result,'{data,invitation}',jsonb_build_object('tipo','alumno','codigo',v_inv.codigo),true);update public.app_mutation_requests set result=v_result where request_id=p_request_id;return v_result;end if;return public.app_mutate_v160_pre_invites_059(p_operation,p_payload,p_request_id);end $function$

